[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/contact/ContactMessageService.java", "content": "package com.example.contact;

import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

@Service
public class ContactMessageService {

    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();

    public void add(String name, String email, String phone, String message) {
        messages.add(new ContactMessage(name, email, phone, message, Instant.now()));
    }

    public List<ContactMessage> findAllNewestFirst() {
        return messages.stream()
                .sorted(Comparator.comparing(ContactMessage::sentAt).reversed())
                .toList();
    }
}
